	(1820,	1322,	'_simple_recipe_pro_ingredients',	'[{\"ingredient\":\"Salad Ingredients:\",\"portion\":\"\",\"portion_decimal\":0,\"caloric_portion\":\"\"},{\"ingredient\":\"cups Beets, Red & Yellow, cubed\",\"portion\":\"3\",\"portion_decimal\":3,\"caloric_portion\":\"\"},{\"ingredient\":\"cups Butternut Squash, cubed\",\"portion\":\"2 1/2\",\"portion_decimal\":2.5,\"caloric_portion\":\"\"},{\"ingredient\":\"cups Sweet Potato, cubed \",\"portion\":\"2 1/2\",\"portion_decimal\":2.5,\"caloric_portion\":\"\"},{\"ingredient\":\"cup Roasted Red Onion\",\"portion\":\"1\",\"portion_decimal\":1,\"caloric_portion\":\"\"},{\"ingredient\":\"oz fresh kale (preferably Tuscan, and young leaves)\",\"portion\":\"12\",\"portion_decimal\":12,\"caloric_portion\":\"\"},{\"ingredient\":\"cup dried cranberries\",\"portion\":\"1/2\",\"portion_decimal\":0.5,\"caloric_portion\":\"\"},{\"ingredient\":\"cup Roasted Pumpkin & Sunflower Seeds\",\"portion\":\"1/2\",\"portion_decimal\":0.5,\"caloric_portion\":\"\"},{\"ingredient\":\"Dressing Ingredients:\",\"portion\":\"\",\"portion_decimal\":0,\"caloric_portion\":\"\"},{\"ingredient\":\"oz fresh or frozen Cranberries\",\"portion\":\"12\",\"portion_decimal\":12,\"caloric_portion\":\"\"},{\"ingredient\":\"cup water\",\"portion\":\"1\",\"portion_decimal\":1,\"caloric_portion\":\"\"},{\"ingredient\":\"cup Raw Sugar \",\"portion\":\"1/4 \",\"portion_decimal\":0.25,\"caloric_portion\":\"\"},{\"ingredient\":\"tablespoon Raw Honey\",\"portion\":\"1\",\"portion_decimal\":1,\"caloric_portion\":\"\"},{\"ingredient\":\" 1/2 package Stevia – to taste\",\"portion\":\"1\",\"portion_decimal\":1,\"caloric_portion\":\"\"},{\"ingredient\":\"cup Balsamic Vinegar\",\"portion\":\"1\",\"portion_decimal\":1,\"caloric_portion\":\"\"},{\"ingredient\":\"cup Raw Apple Cider Vinegar\",\"portion\":\"1/4 \",\"portion_decimal\":0.25,\"caloric_portion\":\"\"},{\"ingredient\":\"tablespoon Dijon Mustard\",\"portion\":\"1\",\"portion_decimal\":1,\"caloric_portion\":\"\"},{\"ingredient\":\"tablespoon fresh Lemon juice\",\"portion\":\"1\",\"portion_decimal\":1,\"caloric_portion\":\"\"},{\"ingredient\":\"cups Olive Oil\",\"portion\":\"1 1/2\",\"portion_decimal\":1.5,\"caloric_portion\":\"\"},{\"ingredient\":\"teaspoon Savory Spice Store Catanzaro seasoning\",\"portion\":\"1\",\"portion_decimal\":1,\"caloric_portion\":\"\"},{\"ingredient\":\"teaspoon Salt\",\"portion\":\"1/2 \",\"portion_decimal\":0.5,\"caloric_portion\":\"\"}]'),
	(1821,	1322,	'_simple_recipe_pro_plaintext',	'Name: Kale & Cranberry Salad with Roasted Root Vegetables\r\nDescription:\r\n\r\nPrep Time: 00:00\r\nCook Time: 00:00\r\nServing Size: \r\nTotal Servings: 8\r\nIngredients:\r\n Salad Ingredients:\r\n3 cups Beets, Red & Yellow, cubed\r\n2 1/2 cups Butternut Squash, cubed\r\n2 1/2 cups Sweet Potato, cubed \r\n1 cup Roasted Red Onion\r\n12 oz fresh kale (preferably Tuscan, and young leaves)\r\n1/2 cup dried cranberries\r\n1/2 cup Roasted Pumpkin & Sunflower Seeds\r\n Dressing Ingredients:\r\n12 oz fresh or frozen Cranberries\r\n1 cup water\r\n1/4  cup Raw Sugar \r\n1 tablespoon Raw Honey\r\n1  1/2 package Stevia – to taste\r\n1 cup Balsamic Vinegar\r\n1/4  cup Raw Apple Cider Vinegar\r\n1 tablespoon Dijon Mustard\r\n1 tablespoon fresh Lemon juice\r\n1 1/2 cups Olive Oil\r\n1 teaspoon Savory Spice Store Catanzaro seasoning\r\n1/2  teaspoon Salt\r\n\r\nDirections:\r\n<strong>Dressing Directions:</strong>\r\n<ul>\r\n 	<li>In a small sauce pan, place fresh cranberries, water and sugar over medium heat. Let it come to a boil and once the first cranberry pops, simmer for about 5 minutes until all the cranberries pop open, set aside to cool.</li>\r\n 	<li>Place the cranberries in a blender, add the vinegars, mustard, lemon juice, oil, seasoning and salt and blend until smooth.</li>\r\n 	<li>Add Stevia to taste and adjust seasoning if necessary.</li>\r\n</ul>\r\n&nbsp;\r\n\r\n<strong>Salad Directions:</strong>\r\n<ul>\r\n 	<li>To roast the vegetables: cut into even size cubes about 1”. Place in separate roasting pans, coat with a small amount of coconut oil, season with salt and roast at high heat, 450F for 30 to 40 minutes, stirring every 10 minutes or so.</li>\r\n 	<li>Trim kale by removing stems/stalks and shredding into strips.</li>\r\n 	<li>Toss in a bowl with the dressing, working it through with your hands.</li>\r\n 	<li>Layer on a platter with the kale topped with the roasted vegetables and finishing with the feta, dried cranberries and seeds.</li>\r\n 	<li> Reserve remaining dressing until ready to serve.</li>\r\n</ul>\r\nNotes:\r\n\r\n'),
	(1822,	1322,	'_simple_recipe_pro_nutrition_data',	'{\"servingsize_oz\":null,\"servingsize\":\"\",\"calories\":\"\",\"caloriesfat\":\"\",\"totalfat\":\"\",\"saturatedfat\":\"\",\"cholesterol\":\"\",\"sodium\":\"\",\"carbohydrate\":\"\",\"dietaryfiber\":\"\",\"sugars\":\"\",\"protein\":\"\"}'),
	(1823,	1322,	'_postdata',	'a:102:{s:8:\"_wpnonce\";s:10:\"3c1cb53104\";s:16:\"_wp_http_referer\";s:87:\"/wp-admin/post.php?post=1322&action=edit&tasty_recipes_message=converted_recipe_success\";s:7:\"user_ID\";i:5;s:6:\"action\";s:8:\"editpost\";s:14:\"originalaction\";s:8:\"editpost\";s:11:\"post_author\";i:1;s:9:\"post_type\";s:4:\"post\";s:20:\"original_post_status\";s:7:\"publish\";s:10:\"referredby\";s:66:\"https://tasteofhealing.com/wp-admin/post.php?post=1322&action=edit\";s:25:\"_wp_original_http_referer\";s:66:\"https://tasteofhealing.com/wp-admin/post.php?post=1322&action=edit\";s:7:\"post_ID\";s:4:\"1322\";s:20:\"meta-box-order-nonce\";s:10:\"2cddb473dd\";s:20:\"closedpostboxesnonce\";s:10:\"8c191fae4c\";s:10:\"post_title\";s:51:\"Kale & Cranberry Salad with Roasted Root Vegetables\";s:20:\"samplepermalinknonce\";s:10:\"33a3b36cf0\";s:7:\"content\";s:1273:\"<p style=\"text-align: center;\"><a href=\"http://tasteofhealing.com/wp-content/uploads/2017/11/Roasted-Root-Salad.jpg\"><img class=\"alignnone wp-image-1325\" src=\"http://tasteofhealing.com/wp-content/uploads/2017/11/Roasted-Root-Salad-226x300.jpg\" alt=\"\" width=\"351\" height=\"466\" /></a></p>\r\nKale; that hardy salad green that is oh so trendy, we know it\'s loaded with antioxidants and really healthy, but if not done right the bouncy, hardy greens can be rather unappetizing!\r\n\r\nThe trick I have found, is to dress up the kale with a tangy dressing, and really give it a good massage to evenly distribute the dressing. My favorite type of kale to use is a combination of the Curly and Lancino Kale, these hardy leaves hold up well when dressed and taste quite delicious once they are marinated, perfect for your holiday take along dishes!\r\n\r\nThe kale provides a delicious base for a variety of toppings; my favorite winter addition is  a medley of beautiful, jewel like roasted root vegetables, finished with lightly toasted seeds and cranberries, and perhaps a little crumbled feta, perfection!\r\n\r\nI hope you enjoy this crowd pleaser recipe, it is gorgeous languishing on a large platter, or plated individually with some chicken or salmon added.\r\n\r\nEnjoy!\r\n\r\n[simple-recipe]\";s:10:\"wp-preview\";s:0:\"\";s:18:\"hidden_post_status\";s:7:\"publish\";s:11:\"post_status\";s:7:\"publish\";s:20:\"hidden_post_password\";s:0:\"\";s:22:\"hidden_post_visibility\";s:6:\"public\";s:10:\"visibility\";s:6:\"public\";s:13:\"post_password\";s:0:\"\";s:2:\"mm\";s:2:\"11\";s:2:\"jj\";s:2:\"23\";s:2:\"aa\";s:4:\"2017\";s:2:\"hh\";s:2:\"04\";s:2:\"mn\";s:2:\"49\";s:2:\"ss\";s:2:\"10\";s:9:\"hidden_mm\";s:2:\"11\";s:6:\"cur_mm\";s:2:\"06\";s:9:\"hidden_jj\";s:2:\"23\";s:6:\"cur_jj\";s:2:\"06\";s:9:\"hidden_aa\";s:4:\"2017\";s:6:\"cur_aa\";s:4:\"2018\";s:9:\"hidden_hh\";s:2:\"04\";s:6:\"cur_hh\";s:2:\"20\";s:9:\"hidden_mn\";s:2:\"49\";s:6:\"cur_mn\";s:2:\"18\";s:16:\"original_publish\";s:6:\"Update\";s:4:\"save\";s:6:\"Update\";s:13:\"post_category\";a:5:{i:0;s:1:\"0\";i:1;s:3:\"173\";i:2;s:3:\"176\";i:3;s:3:\"154\";i:4;s:3:\"161\";}s:11:\"newcategory\";s:17:\"New Category Name\";s:18:\"newcategory_parent\";s:2:\"-1\";s:24:\"_ajax_nonce-add-category\";s:10:\"04317751eb\";s:9:\"tax_input\";a:2:{s:8:\"post_tag\";a:4:{i:0;i:275;i:1;i:250;i:2;i:273;i:3;i:274;}s:14:\"recipe-filters\";a:1:{i:0;s:1:\"0\";}}s:6:\"newtag\";a:1:{s:8:\"post_tag\";s:0:\"\";}s:17:\"newrecipe-filters\";s:15:\"New Filter Name\";s:24:\"newrecipe-filters_parent\";s:2:\"-1\";s:30:\"_ajax_nonce-add-recipe-filters\";s:10:\"3294d64c99\";s:13:\"_thumbnail_id\";s:4:\"1325\";s:19:\"post_meta_box_nonce\";s:10:\"0c618f1ca3\";s:15:\"post_has_recipe\";s:0:\"\";s:9:\"recipe_ID\";s:0:\"\";s:20:\"recipe_active_editor\";s:0:\"\";s:10:\"recipename\";s:51:\"Kale & Cranberry Salad with Roasted Root Vegetables\";s:8:\"portions\";a:21:{i:0;s:0:\"\";i:1;s:1:\"3\";i:2;s:5:\"2 1/2\";i:3;s:5:\"2 1/2\";i:4;s:1:\"1\";i:5;s:2:\"12\";i:6;s:3:\"1/2\";i:7;s:3:\"1/2\";i:8;s:0:\"\";i:9;s:2:\"12\";i:10;s:1:\"1\";i:11;s:4:\"1/4 \";i:12