	(3323, 33792, '_simple_recipe_pro_image', 'http://tasty.handbuilt.co/wp-content/uploads/2017/11/Korean-BBQ-Beef-Tacos.jpg'),
	(3324, 33792, '_simple_recipe_pro_recipename', 'Buffalo Cauliflower Tacos'),
	(3325, 33792, '_simple_recipe_pro_description', '<p>This colorful, spicy, crispy, mega-yum recipe was inspired by the amazing buffalo “wings” at&nbsp;<a href=\"http://www.jselbys.com/\" data-mce-href=\"http://www.jselbys.com/\">J. Selby’s</a>&nbsp;in Saint Paul and&nbsp;<a href=\"http://sarasullivan.com/buffalo-cauliflower-tacos-avocado-cream/\" data-mce-href=\"http://sarasullivan.com/buffalo-cauliflower-tacos-avocado-cream/\">this recipe</a>&nbsp;from Sarah Sullivan. Thanks to both sources of inspiration!</p>'),
	(3326, 33792, '_simple_recipe_pro_notes', '<p><strong>Gluten Free:</strong>&nbsp;Use GF flour and GF corn tortillas. Note: you may need a few more tablespoons of milk to get the right consistency for the batter when using GF flour.</p><p><strong>Vegan:</strong>&nbsp;use non-dairy milk and skip the sour cream in the sauce.</p><p><strong>Cauliflower Pro Tip:</strong>&nbsp;It helps if you have a greased wire rack to back the cauliflower on – this allows excess batter to drip down and promotes crispiness.&nbsp;<img class=\"emoji\" draggable=\"false\" src=\"https://s.w.org/images/core/emoji/2.3/svg/1f44d-1f3fc.svg\" alt=\"??\" data-mce-resize=\"false\" data-mce-placeholder=\"1\" data-wp-emoji=\"1\" data-mce-src=\"https://s.w.org/images/core/emoji/2.3/svg/1f44d-1f3fc.svg\">&nbsp;But it works fine without, too.</p><p><strong>Notes about texture:</strong>&nbsp;The texture as written is pretty firm and crispy, but not deep-fried-level crispy. Not surprisingly, you’d have to deep fry to achieve that. Which you could totally do!&nbsp;<a href=\"https://pinchofyum.com/crispy-fish-tacos-jalapeno-sauce\" data-mce-href=\"https://pinchofyum.com/crispy-fish-tacos-jalapeno-sauce\">Here’s a recipe with a deep fry batter</a>&nbsp;that I’d recommend if you want to spend the time doing that (it’s delish). But to me, this is a really great middle-of-the-road alternative that is a) much easier, b) healthier, and c) still really tasty!</p>'),
	(3327, 33792, '_simple_recipe_pro_prep_time', '15 mins'),
	(3328, 33792, '_simple_recipe_pro_cook_time', '00:30'),
	(3329, 33792, '_simple_recipe_pro_wait_time', ''),
	(3330, 33792, '_simple_recipe_pro_total_time', '50 mins'),
	(3331, 33792, '_simple_recipe_pro_serving_size', '2 tacos'),
	(3332, 33792, '_simple_recipe_pro_servings', '8 tacos'),
	(3333, 33792, '_simple_recipe_pro_difficulty', 'Easy'),
	(3334, 33792, '_simple_recipe_pro_cuisine', 'Mexican Fusion'),
	(3335, 33792, '_simple_recipe_pro_directions', '<ol><li><strong>Batter the cauliflower:&nbsp;</strong>Preheat oven to 450 degrees. Whisk flour, milk, salt, pepper, and garlic powder. Dip cauliflower pieces in the batter and let excess drip off. Place on parchment-lined baking sheet. Bake on an upper rack for 15-20 minutes until lightly crisped and browned.</li><li><strong>Spice the cauliflower:&nbsp;</strong>Gently toss the baked cauliflower in a bowl with the hot sauce. Return to pan. Bake for another 5-10 minutes.</li><li><strong>Avocado Crema:&nbsp;</strong>Mix all ingredients in a food processor or blender until smooth.</li><li><strong>Slaw:&nbsp;</strong>Toss the slaw with some of the avocado crema until it’s nice and creamy.</li><li><strong>Tacos:&nbsp;</strong>Fill each tortilla with slaw, cauliflower, a drizzle of avocado crema, and cilantro. Perfection!</li></ol>'),
	(3336, 33792, '_simple_recipe_pro_ingredients', 'a:16:{i:0;a:4:{s:10:\"ingredient\";s:26:\"Buffalo Cauliflower Tacos:\";s:7:\"portion\";s:0:\"\";s:15:\"portion_decimal\";d:0;s:15:\"caloric_portion\";s:0:\"\";}i:1;a:4:{s:10:\"ingredient\";s:9:\"cup flour\";s:7:\"portion\";s:1:\"1\";s:15:\"portion_decimal\";d:1;s:15:\"caloric_portion\";s:0:\"\";}i:2;a:4:{s:10:\"ingredient\";s:8:\"cup milk\";s:7:\"portion\";s:1:\"1\";s:15:\"portion_decimal\";d:1;s:15:\"caloric_portion\";s:0:\"\";}i:3;a:4:{s:10:\"ingredient\";s:17:\"tsp garlic powder\";s:7:\"portion\";s:3:\"1/4\";s:15:\"portion_decimal\";d:0.25;s:15:\"caloric_portion\";s:0:\"\";}i:4;a:4:{s:10:\"ingredient\";s:16:\"head cauliflower\";s:7:\"portion\";s:1:\"1\";s:15:\"portion_decimal\";d:1;s:15:\"caloric_portion\";s:0:\"\";}i:5;a:4:{s:10:\"ingredient\";s:13:\"cup hot sauce\";s:7:\"portion\";s:3:\"3/4\";s:15:\"portion_decimal\";d:0.75;s:15:\"caloric_portion\";s:0:\"\";}i:6;a:4:{s:10:\"ingredient\";s:24:\"shredded cabbage or slaw\";s:7:\"portion\";s:0:\"\";s:15:\"portion_decimal\";d:0;s:15:\"caloric_portion\";s:0:\"\";}i:7;a:4:{s:10:\"ingredient\";s:22:\"chopped fresh cilantro\";s:7:\"portion\";s:0:\"\";s:15:\"portion_decimal\";d:0;s:15:\"caloric_portion\";s:0:\"\";}i:8;a:4:{s:10:\"ingredient\";s:9:\"tortillas\";s:7:\"portion\";s:0:\"\";s:15:\"portion_decimal\";d:0;s:15:\"caloric_portion\";s:0:\"\";}i:9;a:4:{s:10:\"ingredient\";s:14:\"Avocado Crema:\";s:7:\"portion\";s:0:\"\";s:15:\"portion_decimal\";d:0;s:15:\"caloric_portion\";s:0:\"\";}i:10;a:4:{s:10:\"ingredient\";s:8:\"avocados\";s:7:\"portion\";s:1:\"2\";s:15:\"portion_decimal\";d:2;s:15:\"caloric_portion\";s:0:\"\";}i:11;a:4:{s:10:\"ingredient\";s:12:\"clove garlic\";s:7:\"portion\";s:1:\"1\";s:15:\"portion_decimal\";d:1;s:15:\"caloric_portion\";s:0:\"\";}i:12;a:4:{s:10:\"ingredient\";s:14:\"cup sour cream\";s:7:\"portion\";s:3:\"1/4\";s:15:\"portion_decimal\";d:0.25;s:15:\"caloric_portion\";s:0:\"\";}i:13;a:4:{s:10:\"ingredient\";s:9:\"cup water\";s:7:\"portion\";s:3:\"1/4\";s:15:\"portion_decimal\";d:0.25;s:15:\"caloric_portion\";s:0:\"\";}i:14;a:4:{s:10:\"ingredient\";s:8:\"tsp salt\";s:7:\"portion\";s:3:\"1/2\";s:15:\"portion_decimal\";d:0.5;s:15:\"caloric_portion\";s:0:\"\";}i:15;a:4:{s:10:\"ingredient\";s:15:\"squeeze of lime\";s:7:\"portion\";s:0:\"\";s:15:\"portion_decimal\";d:0;s:15:\"caloric_portion\";s:0:\"\";}}'),
	(3337, 33792, '_simple_recipe_pro_plaintext', 'Name: Buffalo Cauliflower Tacos\r\nDescription:\r\n<p>This colorful, spicy, crispy, mega-yum recipe was inspired by the amazing buffalo “wings” at&nbsp;<a href=\"http://www.jselbys.com/\" data-mce-href=\"http://www.jselbys.com/\">J. Selby’s</a>&nbsp;in Saint Paul and&nbsp;<a href=\"http://sarasullivan.com/buffalo-cauliflower-tacos-avocado-cream/\" data-mce-href=\"http://sarasullivan.com/buffalo-cauliflower-tacos-avocado-cream/\">this recipe</a>&nbsp;from Sarah Sullivan. Thanks to both sources of inspiration!</p>\r\n\r\nPrep Time: 15 mins\r\nCook Time: 30 mins\r\nInactive Time: \r\nTotal Time: \r\nServing Size: 2 tacos\r\nTotal Servings: 8 tacos\r\n\r\nIngredients:\r\n Buffalo Cauliflower Tacos:\r\n1 cup flour\r\n1 cup milk\r\n1/4 tsp garlic powder\r\n1 head cauliflower\r\n3/4 cup hot sauce\r\n shredded cabbage or slaw\r\n chopped fresh cilantro\r\n tortillas\r\n Avocado Crema:\r\n2 avocados\r\n1 clove garlic\r\n1/4 cup sour cream\r\n1/4 cup water\r\n1/2 tsp salt\r\n squeeze of lime\r\n\r\nDirections:\r\n<ol><li><strong>Batter the cauliflower:&nbsp;</strong>Preheat oven to 450 degrees. Whisk flour, milk, salt, pepper, and garlic powder. Dip cauliflower pieces in the batter and let excess drip off. Place on parchment-lined baking sheet. Bake on an upper rack for 15-20 minutes until lightly crisped and browned.</li><li><strong>Spice the cauliflower:&nbsp;</strong>Gently toss the baked cauliflower in a bowl with the hot sauce. Return to pan. Bake for another 5-10 minutes.</li><li><strong>Avocado Crema:&nbsp;</strong>Mix all ingredients in a food processor or blender until smooth.</li><li><strong>Slaw:&nbsp;</strong>Toss the slaw with some of the avocado crema until it’s nice and creamy.</li><li><strong>Tacos:&nbsp;</strong>Fill each tortilla with slaw, cauliflower, a drizzle of avocado crema, and cilantro. Perfection!</li></ol>\r\n\r\nNotes:\r\n<p><strong>Gluten Free:</strong>&nbsp;Use GF flour and GF corn tortillas. Note: you may need a few more tablespoons of milk to get the right consistency for the batter when using GF flour.</p><p><strong>Vegan:</strong>&nbsp;use non-dairy milk and skip the sour cream in the sauce.</p><p><strong>Cauliflower Pro Tip:</strong>&nbsp;It helps if you have a greased wire rack to back the cauliflower on – this allows excess batter to drip down and promotes crispiness.&nbsp;<img class=\"emoji\" draggable=\"false\" src=\"https://s.w.org/images/core/emoji/2.3/svg/1f44d-1f3fc.svg\" alt=\"??\" data-mce-resize=\"false\" data-mce-placeholder=\"1\" data-wp-emoji=\"1\" data-mce-src=\"https://s.w.org/images/core/emoji/2.3/svg/1f44d-1f3fc.svg\">&nbsp;But it works fine without, too.</p><p><strong>Notes about texture:</strong>&nbsp;The texture as written is pretty firm and crispy, but not deep-fried-level crispy. Not surprisingly, you’d have to deep fry to achieve that. Which you could totally do!&nbsp;<a href=\"https://pinchofyum.com/crispy-fish-tacos-jalapeno-sauce\" data-mce-href=\"https://pinchofyum.com/crispy-fish-tacos-jalapeno-sauce\">Here’s a recipe with a deep fry batter</a>&nbsp;that I’d recommend if you want to spend the time doing that (it’s delish). But to me, this is a really great middle-of-the-road alternative that is a) much easier, b) healthier, and c) still really tasty!</p>\r\n'),
