	(3425, 33827, '[simple-recipe:33827a]', ';Name: Simple Recipe Pro recipe 3\r\n;Image: http://tasty.handbuilt.co/wp-content/uploads/2017/11/Korean-BBQ-Beef-Tacos.jpg\r\n\r\n;Description:\r\n			Some description\r\n;Prep Time: 10 mins\r\n;Cook Time: 20 mins\r\n;Wait Time: 40 mins\r\n;Total Time: 50 mins\r\n;Total Servings: 22 muffins \r\n\r\n;Ingredients:\r\n			<ul><li>1 apple</li><li>1 carrot</li></ul><h4>A group of ingredients</h4><ul><li>More ingredients</li><li>Another ingredient</li></ul><p>A paragraph</p>\r\n\r\n;Directions:\r\n			<ol><li>Do this</li><li>Then that</li><li><strong>Bold</strong>, <em>italic</em>, <span style=\"text-decoration: underline;\" data-mce-style=\"text-decoration: underline;\">underline</span>, <del>strikethrough</del>, and <a href=\"https://google.com\" target=\"_blank\" rel=\"nofollow\">a link</a></li></ol>\r\n\r\n;Notes:\r\n			<p>Notes</p>\r\n\r\n;By: Raquel Smith\r\n\r\n;Recipe Type: Dinner\r\n;Cuisine: American\r\n;Difficulty: Easy\r\n\r\n;Serving Size: 1 muffin\r\n;Calories: 10 kcal\r\n;Total Fat: 100g\r\n;Saturated Fat: 5g\r\n;Cholesterol: 100mg\r\n;Sodium: 500mg\r\n;Carbohydrate: 10g\r\n;Dietary Fiber: 20g\r\n;Sugars: 30g\r\n;Protein: 40g\r\n;Other: '),
